import React, { useEffect, useState } from "react"; 
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();
  const [faqs, setFaqs] = useState([]);
  const [newQuestion, setNewQuestion] = useState("");

  const menuItems = [
    { name: "Home", route: "/home" },
    { name: "Profile", route: "/profile" },
    { name: "Settings", route: "/settings" },
    { name: "About", route: "/about" },
    { name: "Logout", route: "/" }
  ];

  useEffect(() => {
    const storedFaqs = JSON.parse(localStorage.getItem("faqs")) || [];
    setFaqs(storedFaqs);
  }, []);

  const handleAskQuestion = () => {
    if (!newQuestion.trim()) return;

    const newFaq = {
      id: Date.now(),
      question: newQuestion,
      answer: null,
    };

    const updatedFaqs = [...faqs, newFaq];
    setFaqs(updatedFaqs);
    localStorage.setItem("faqs", JSON.stringify(updatedFaqs));
    setNewQuestion("");
  };

  return (
    <div className="homepage-container">
      <aside className="sidebar">
        <div className="sidebar-logo">Parking System</div>
        {menuItems.map((item, index) => (
          <button
            key={index}
            className="sidebar-btn"
            onClick={() => {
              if (item.name === "Logout") localStorage.removeItem("user");
              navigate(item.route);
            }}
          >
            {item.name}
          </button>
        ))}
      </aside>

      <main className="main-content">
        <section className="hero-section">
          <h1>Welcome to Parking Slot System</h1>
          <p>Manage your bookings, view facilities, and update your profile all in one place.</p>
          <button className="start-btn" onClick={() => navigate("/booking")}>
            Start Booking
          </button>
        </section>

        {/* FAQ Section */}
        <section className="faq-section card">
          <h2>FAQs</h2>
          <div className="faq-form">
            <textarea
              value={newQuestion}
              onChange={(e) => setNewQuestion(e.target.value)}
              placeholder="Ask a question..."
            />
            <button onClick={handleAskQuestion}>Submit</button>
          </div>
          <ul className="faq-list">
            {faqs.map((faq) => (
              <li key={faq.id}>
                <strong>Q:</strong> {faq.question} <br />
                <strong>A:</strong> {faq.answer || "Pending reply..."}
              </li>
            ))}
          </ul>
        </section>
      </main>
    </div>
  );
}

export default HomePage;
